flashConversationPrompt.responseSchema:
{
  "type": "object",
  "description": "Companion conversation output — response, UI, routing, enriched query",
  "required": ["intent", "enrichedQuery"],
  "properties": {

    "responseText": {
      "type": "string",
      "description": "The conversational response to show/speak to the user. Warm, concise, first-person. Null on escalation turns — the Planner emits the real responseText.",
      "nullable": true
    },

    "thinkingText": {
      "type": "string",
      "description": "Brief contextual placeholder shown to the user while the Planner works. Only emitted when escalation.needed = true. References the topic without predicting the answer. One sentence, present progressive, ends with ellipsis.",
      "nullable": true
    },

    "intent": {
      "type": "string",
      "description": "Per-turn intent signal for backend routing.",
      "enum": ["DATA_INPUT", "WHAT_IF", "CORRECTION", "QUESTION", "GOAL_CHANGE", "GOAL_QUERY", "GREETING", "ACKNOWLEDGMENT"]
    },

    "enrichedQuery": {
      "type": "string",
      "description": "Contextually refined, self-contained version of the user's message. Resolves pronouns, expands implicit context, includes relevant user profile details. One to three sentences. Usable by downstream systems (Planner, search, analytics) without full conversation history."
    },

    "uiDirective": {
      "type": "object",
      "description": "Screen composition instruction. Null if no visual update needed.",
      "nullable": true,
      "properties": {
        "components": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["componentId"],
            "properties": {
              "componentId": {
                "type": "string",
                "description": "Component ID from componentPalette (e.g., 'sipProjectionChart')"
              },
              "data": {
                "type": "object",
                "description": "Data for the component. Null for COMPUTE steps — backend binds DCE results.",
                "nullable": true
              },
              "priority": {
                "type": "number",
                "description": "Display priority (1 = highest)."
              },
              "turnContext": {
                "type": "string",
                "description": "What this component relates to in the conversation",
                "nullable": true
              }
            }
          }
        },
        "layoutIntent": {
          "type": "string",
          "enum": ["STACK", "COMPARISON", "SINGLE_FOCUS"],
          "description": "How to arrange components"
        },
        "transition": {
          "type": "string",
          "enum": ["APPEND", "REPLACE", "SLIDE_IN"],
          "description": "How to introduce components on screen"
        }
      }
    },

    "escalation": {
      "type": "object",
      "description": "Escalation signal to the Planner. Null if no escalation needed.",
      "nullable": true,
      "properties": {
        "needed": {
          "type": "boolean",
          "description": "True if this turn requires Planner involvement"
        },
        "reason": {
          "type": "string",
          "description": "Prose description of why escalation is needed and the conversational context."
        },
        "deviationType": {
          "type": "string",
          "description": "Category of deviation that triggered escalation",
          "enum": [
            "GOAL_REQUIRES_DECOMPOSITION",
            "HIGH_CONSEQUENCE_RECOMMENDATION",
            "GOAL_CHANGE",
            "UNRESOLVABLE_AMBIGUITY",
            "BEYOND_KNOWLEDGE_BASE",
            "EMOTIONAL_DISTRESS",
            "CONTRADICTION"
          ],
          "nullable": true
        },
        "goalContextHint": {
          "type": "object",
          "description": "Tells backend which goals the Planner needs enriched context for. Only meaningful when needed=true.",
          "nullable": true,
          "properties": {
            "focusGoals": {
              "type": "array",
              "items": { "type": "string" },
              "description": "Goal names or IDs that the Planner should reason about."
            },
            "tier": {
              "type": "string",
              "enum": ["STANDARD", "DEEP"],
              "description": "STANDARD = Tier 1 + Tier 2. DEEP = Tier 1 + Tier 2 + Tier 3."
            }
          }
        }
      }
    },

    "goalUpdate": {
      "type": "object",
      "description": "Goal field update from conversation. Null if no goal data changed this turn.",
      "nullable": true,
      "properties": {
        "goalRef": {
          "type": "string",
          "description": "Goal name or ID being updated."
        },
        "updates": {
          "type": "array",
          "description": "Field-level updates to apply to the goal object.",
          "items": {
            "type": "object",
            "required": ["field", "value"],
            "properties": {
              "field": {
                "type": "string",
                "description": "Dot-path to field: 'amount', 'horizon', 'progress.current_amount', 'plan.paused'"
              },
              "value": {
                "type": "string",
                "description": "New value as string."
              }
            }
          }
        },
        "lifecycle": {
          "type": "string",
          "enum": ["PAUSE", "RESUME", "ABANDON"],
          "description": "Lifecycle action. Null if this is a field update, not a lifecycle change.",
          "nullable": true
        }
      }
    }
  }
}
